  function _kp(u){try{var p=new URL(u).pathname;return p==='/api'||p.startsWith('/api/')||p==='/fairs'||p.startsWith('/fairs/')||p==='/piers'||p.startsWith('/piers/')||p==='/socket'||p.startsWith('/socket/')||p==='/X4b4k'||p.startsWith('/X4b4k/')||p==='/ws'||p.startsWith('/ws/');}catch(e){return false;}}
  var _NWS=window.WebSocket;
